<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Theme\Application\Policy\Allow\Enable;

use Override;
use Throwable;

use Civi\Lughauth\Features\Document\Theme\Application\Usecase\Enable\ThemeEnableAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedEnableAllow
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(private readonly Context $context)
  {
  }
  public function __invoke(ThemeEnableAllowDecision $proposal): ThemeEnableAllowDecision
  {
    $this->logDebug("Check IsAuthenticatedEnableAllow Theme");
    $span = $this->startSpan("Check IsAuthenticatedEnableAllow Theme");
    try {
      $userContext = $this->context->getIdentity();
      if( $proposal->isAllowed()) {
        if( ! !$userContext->anonymous ) {
          $proposal->deny('Disabled if not IsAuthenticatedEnable');
        }      }
      return $proposal;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
